"""Print each slide's text in deck order: headings, paragraphs, img alt text, svg text, speaker notes."""
import json, re, sys, html
from html.parser import HTMLParser

root = sys.argv[1]
order = json.load(open(root + "/project/deck.json"))["order"]


class P(HTMLParser):
    def __init__(self):
        super().__init__()
        self.out, self.buf, self.aside = [], [], False

    def flush(self):
        t = re.sub(r"\s+", " ", "".join(self.buf)).strip()
        if t:
            self.out.append(("NOTES: " if self.aside else "") + t)
        self.buf = []

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if tag in ("p", "h1", "h2", "h3", "li", "div", "section", "td", "th", "tr", "text", "aside", "svg", "table"):
            self.flush()
        if tag == "aside":
            self.aside = True
        if tag == "img":
            self.buf.append(" [[" + (a.get("alt") or "img") + "]] ")
        if tag == "svg" and a.get("aria-label"):
            self.out.append("SVG: " + a["aria-label"])
        if tag == "br":
            self.buf.append(" / ")

    def handle_endtag(self, tag):
        if tag in ("p", "h1", "h2", "h3", "li", "td", "th", "text", "aside", "tr", "div"):
            self.flush()
        if tag == "aside":
            self.aside = False

    def handle_data(self, d):
        self.buf.append(d)


for n, sid in enumerate(order, 1):
    p = P()
    p.feed(open(f"{root}/project/slides/{sid}.html").read())
    p.flush()
    print(f"\n===== slide {n}: {sid} =====")
    for line in p.out:
        print(line)
