def surv(median, lo, hi, x):
    if x <= 0:
        return 1.0
    sigma = lo if x < median else hi
    return 0.5 * math.erfc(math.log(x / median) / sigma / math.sqrt(2.0))


class Dist:
    def __init__(self, p10, p50, p90):
        self.m = max(p50, 0.01)
        self.lo = max(SIGMA_FLOOR, math.log(self.m / max(min(p10, self.m), 0.01)) / Z90)
        self.hi = max(SIGMA_FLOOR, math.log(max(p90, self.m) / self.m) / Z90)
        self.p90 = max(p90, self.m)

    def s(self, x):
        return surv(self.m, self.lo, self.hi, x)

    def hazard(self, x):
        x = max(x, 1e-3)
        sigma = self.lo if x < self.m else self.hi
        z = math.log(x / self.m) / sigma
        s = self.s(x)
        return math.exp(-0.5 * z * z) / (x * sigma * math.sqrt(2 * math.pi)) / s if s > 0 else 0.0


