import itertools, sys

PROTAN = ((0.152286, 1.052583, -0.204868), (0.114503, 0.786281, 0.099216), (-0.003882, -0.048116, 1.051998))
DEUTAN = ((0.367322, 0.860646, -0.227968), (0.280085, 0.672501, 0.047413), (-0.011820, 0.042940, 0.968881))


def linear(hex_):
    rgb = [int(hex_.lstrip("#")[i:i + 2], 16) / 255 for i in (0, 2, 4)]
    return [c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4 for c in rgb]


def oklab(rgb):
    r, g, b = (max(0.0, c) for c in rgb)
    l = (0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b) ** (1 / 3)
    m = (0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b) ** (1 / 3)
    s = (0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b) ** (1 / 3)
    return (0.2104542553 * l + 0.7936177850 * m - 0.0040720468 * s, 1.9779984951 * l - 2.4285922050 * m + 0.4505937099 * s,
            0.0259040371 * l + 0.7827717662 * m - 0.8086757660 * s)


def sim(rgb, matrix):
    return [sum(k * c for k, c in zip(row, rgb)) for row in matrix]


def de(a, b):
    return 100 * sum((x - y) ** 2 for x, y in zip(a, b)) ** 0.5


def luminance(rgb):
    return 0.2126 * rgb[0] + 0.7152 * rgb[1] + 0.0722 * rgb[2]


colors = sys.argv[1].split(",")
surface = sys.argv[2] if len(sys.argv) > 2 else "#fcfcfb"
lin = {c: linear(c) for c in colors}
worst = {"normal": (1e9, None), "protan": (1e9, None), "deutan": (1e9, None)}
for a, b in itertools.combinations(colors, 2):
    for name, matrix in (("normal", None), ("protan", PROTAN), ("deutan", DEUTAN)):
        x, y = (lin[a], lin[b]) if matrix is None else (sim(lin[a], matrix), sim(lin[b], matrix))
        d = de(oklab(x), oklab(y))
        if d < worst[name][0]:
