ADM = re.compile(r"HICACHE_EVT ntp_admit rid=\S+?-c(\d+)-t(\d+) wait_ms=(\d+) pred_wait_ql_ms=(\S+) ")
IO = re.compile(r"HICACHE_EVT s2h_io rid=\S+?-c(\d+)-t(\d+) ")
